#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Migrate ANY FISH image family to the deterministic FISH version (task 2 of notes/big_task.txt):
# transplant the PATCHED overlay source tree of the mainline head (exported from fishwait28:
# ~/fish_traces/overlay_src_fw28.tgz = tracetools rcl rclcpp rclcpp_action tf2 message_filters cyclonedds
# rmw_cyclonedds_cpp, all fishwait12..27 patches applied) into the target image, build it there against the image's own
# Humble, build + test the shims (OpenMP, lock, container), rebuild the packages that instantiate header-level hooks
# (generic subscriptions, intra-process users, benchmark packages), verify the markers, commit <new_tag>.
# Old tags are never touched. Re-runnable (task 4 re-upgrade): the overlay workspace is replaced and rebuilt again.
# Usage: scripts/migrate_overlay.sh <base_image[:tag]> <new_image:tag> [extra packages to rebuild against the overlay ...]
#   env: OVERLAY_TGZ (default ~/fish_traces/overlay_src_fw28.tgz), ROS_WS (default /root/ros_ws if present),
#        SRC_ROOTS / INSTALL for rebuild_header_tracepoint_users.sh (defaults: the ROS_WS), LOG (default /tmp/migrate_<tag>.log)
set -u
BASE=$1; NEW=$2; shift 2; EXTRA_PKGS="$*"
HERE=$(cd "$(dirname "$0")/.." && pwd)
TGZ=${OVERLAY_TGZ:-$HOME/fish_traces/overlay_src_fw28.tgz}
TAG=$(echo "$NEW" | tr ':/' '__'); C=mig_$TAG; LOG=${LOG:-/tmp/migrate_$TAG.log}
docker rm -f $C >/dev/null 2>&1
docker run -d --name $C --entrypoint bash -v "$HERE/docker/overlay_patches":/patches:ro -v "$HERE/scripts":/fish_scripts:ro -v "$TGZ":/overlay_src.tgz:ro "$BASE" -c 'sleep 21600' >/dev/null || { echo "cannot start $BASE" | tee "$LOG"; exit 2; }
{
echo "=== $(date +%T) migrate $BASE -> $NEW"
# 1. overlay sources: replace the core packages by the patched tree; Cyclone packages only where the image has Cyclone
docker exec $C bash -c '
  set -e; W=/root/trace_overlay_ws; mkdir -p $W/src; cd $W/src
  for p in tracetools rcl rclcpp rclcpp_action tf2 message_filters cyclonedds rmw_cyclonedds_cpp; do rm -rf $p; done
  tar -xzf /overlay_src.tgz
  PK="tracetools rcl rclcpp rclcpp_action tf2 message_filters"
  if [ -d /opt/ros/humble/share/rmw_cyclonedds_cpp ] || [ -n "$(ls /opt/ros/humble/lib 2>/dev/null | grep librmw_cyclonedds_cpp)" ]; then PK="$PK cyclonedds rmw_cyclonedds_cpp"; else rm -rf cyclonedds rmw_cyclonedds_cpp; echo "no Cyclone in this image: DDS identity hooks skipped (source_timestamp pairing only)"; fi
  echo "overlay packages: $PK"
  set +u; source /opt/ros/humble/setup.bash; set -u
  cd $W && colcon build --packages-select $PK --cmake-args -DCMAKE_BUILD_TYPE=RelWithDebInfo -DBUILD_TESTING=OFF 2>&1 | tail -12
  grep -c "fish_container_op" $W/install/tracetools/include/tracetools/tracetools/tracetools.h >/dev/null && echo OVERLAY_MARKER_OK || echo OVERLAY_MARKER_MISSING
'
# 2. shims, exactly as build_overlay.sh does
docker exec $C bash -c 'T=/root/trace_overlay_ws/install/tracetools; gcc -shared -fPIC -O2 -o $T/lib/libfish_gomp_shim.so /patches/fish_gomp_shim.c -I$T/include/tracetools -L$T/lib -ltracetools -ldl -Wl,--no-as-needed -l:libgomp.so.1 && echo SHIM_OK; set +u; source /opt/ros/humble/setup.bash; source /root/trace_overlay_ws/install/setup.bash; set -u; bash /patches/test_gomp_shim.sh $T/lib/libfish_gomp_shim.so'
docker exec $C bash -c 'T=/root/trace_overlay_ws/install/tracetools; grep -q fish_lock $T/include/tracetools/tracetools/tracetools.h || exit 0; gcc -shared -fPIC -O2 -o $T/lib/libfish_lock_shim.so /patches/fish_lock_shim.c -I$T/include/tracetools -L$T/lib -ltracetools -ldl -lpthread && echo LOCKSHIM_OK || echo "SHIM_TEST_FAIL lock: build"; set +u; source /opt/ros/humble/setup.bash; source /root/trace_overlay_ws/install/setup.bash; set -u; bash /patches/test_lock_shim.sh $T/lib/libfish_lock_shim.so'
docker exec $C bash -c 'T=/root/trace_overlay_ws/install/tracetools; grep -q fish_container_op $T/include/tracetools/tracetools/tracetools.h || exit 0; LIBDIRS="/opt/ros/humble/lib /root/trace_overlay_ws/install"; for d in /opt/autoware/lib /root/ros_ws/install /workspaces/isaac_ros-dev/install /opt/aas; do [ -d $d ] && LIBDIRS="$LIBDIRS $d"; done; python3 /patches/gen_container_shim.py --libdirs $LIBDIRS 2>&1 | tail -3; bash /patches/test_container_shim.sh $T/lib/libfish_container_shim.so'
# 3. packages that instantiate header-level hooks. A SOURCE workspace (Isaac: /root/ros_ws) is rebuilt IN PLACE with the
#    overlay sourced (its install shadows nothing: it is what the image runs); a prebuilt install (Autoware /opt/autoware)
#    goes through rebuild_header_tracepoint_users.sh (copies the sources into the overlay workspace).
docker exec -e EXTRA_PKGS="$EXTRA_PKGS" $C bash -c '
  set +u; source /opt/ros/humble/setup.bash; set -u
  WS=${ROS_WS:-}; for w in /root/ros_ws /workspaces/isaac_ros-dev; do [ -z "$WS" ] && [ -d $w/src ] && [ -d $w/install ] && WS=$w; done
  if [ -n "$WS" ]; then
    USERS=$(grep -rlE "create_generic_subscription|GenericSubscription|use_intra_process_comms" --include=*.cpp --include=*.hpp $WS/src 2>/dev/null | sed "s|$WS/src/||" | awk -F/ "{print \$1\"/\"\$2}" | sort -u | while read d; do p=$(grep -o "<name>[^<]*" $WS/src/$d/package.xml 2>/dev/null | head -1 | cut -d">" -f2); [ -n "$p" ] && echo $p; done | sort -u | tr "\n" " ")
    PK="$(echo $USERS $EXTRA_PKGS | tr " " "\n" | sort -u | tr "\n" " ")"
    echo "header-hook users rebuilt in place in $WS: $PK"
    set +u; source $WS/install/setup.bash; source /root/trace_overlay_ws/install/setup.bash; set -u
    cd $WS && colcon build --packages-select $PK --cmake-args -DBUILD_TESTING=OFF -DCMAKE_BUILD_TYPE=Release 2>&1 | tail -6
    for p in $PK; do grep -q "^rclcpp_DIR:PATH=/root/trace_overlay_ws/install/rclcpp/" build/$p/CMakeCache.txt 2>/dev/null && echo "[inplace] $p: overlay rclcpp OK" || echo "[inplace] $p: WARNING overlay rclcpp NOT used"; done
    python3 - "$PK" <<PY
import json, os, sys, time
m = "/root/trace_overlay_ws/fish_rebuilt_packages.json"; d = json.load(open(m)) if os.path.exists(m) else {"rebuilt": {}}
d.setdefault("rebuilt_in_place", {}).update({p: {"ws": "$WS", "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())} for p in sys.argv[1].split()})
json.dump(d, open(m, "w"), indent=1)
PY
  elif [ -d /opt/autoware ]; then
    PKGS="$EXTRA_PKGS" bash /fish_scripts/rebuild_header_tracepoint_users.sh 2>&1 | tail -12
  else
    echo "no source workspace / prebuilt install found for header-hook users (library-side hooks only)"
  fi
'
echo "=== $(date +%T) build step done"
} > "$LOG" 2>&1
if grep -q "OVERLAY_MARKER_OK" "$LOG" && ! grep -q "Failed   <<<\|Aborted  <<<\|^SHIM_TEST_FAIL" "$LOG" && grep -q "^SHIM_TEST_OK" "$LOG"; then
  # docker 29.3: `--change 'ENTRYPOINT []'` does not clear the container's --entrypoint bash; a metadata-only build does (2026-10-26)
  docker commit --change 'CMD ["bash","-c","sleep 10800"]' --change "LABEL fish.lineage=mainline" --change "LABEL fish.overlay=fw28-transplant" --change "LABEL fish.migrated_from=$BASE" $C "$NEW-entrybash" >> "$LOG" 2>&1 \
    && printf 'FROM %s\nENTRYPOINT []\nCMD ["bash","-c","sleep 10800"]\n' "$NEW-entrybash" | docker build -q -t "$NEW" - >> "$LOG" 2>&1 && docker rmi "$NEW-entrybash" >> "$LOG" 2>&1 \
    && [ "$(docker inspect --format '{{json .Config.Entrypoint}}' "$NEW")" = null ] && echo COMMITTED >> "$LOG"
else
  echo "NOT COMMITTED (overlay marker / shim test failed)" >> "$LOG"
fi
[ "${KEEP:-0}" = 1 ] && echo "container $C kept for inspection" >> "$LOG" || docker rm -f $C >/dev/null 2>&1; echo DONE >> "$LOG"; tail -3 "$LOG"
